void MenuLoading::SetProgress( s32 progress )
{
	m_LoadingBar->SetPercent( progress );
}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------
bool MenuLoading::LoadingDone()
{
	return m_LoadingBar->GetPercent() == 100;
}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------
void MenuLoading::SelectLoadingHint()
{
	for (int i = 0; i < LH_Count; i++)
	{
		if (IsHintAppropriate(s_hints[i]))
		{
			m_hint = s_hints[i];
			s_hints.erase(i);
			s_hints.push_back(m_hint);
			break;
		}
	}
}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------
bool MenuLoading::IsHintAppropriate(int hint)
{
	CPlayfield* playfield = CPlayfield::GetInstance();

	int level = playfield->m_CurrentLevel + 1;
	int day = playfield->m_CurrentDay + 1;

	if (level == 1 && day == 1)
		return hint == LH_13;
	else if (hint == LH_13)
		return false;

	if (level == 10 && day == 1)
		return hint == LH_14;
	else if (hint == LH_14)
		return false;

	if (level == 11 && day == 1)
		return hint == LH_15;
	else if (hint == LH_15)
		return false;

	if (playfield->getChallenge()->getType() != CT_None)
		return hint == LH_7;
	else if (hint == LH_7)
		return false;

	if (hint == LH_3)
		return level != 2;

	if (hint == LH_6 || hint == LH_10 || hint == LH_11)
		return level != 1;

	if (hint == LH_12)
		return level != 1 && level != 2 && level != 3;

	CLevelStats& stats = playfield->GetLevelStats();

	if (hint == LH_9)
		return stats.WeaponLevel[WT_Hydra] == WL_1;

	if (hint == LH_Boulder)
		return stats.WeaponLevel[WT_Spell] == ST_Boulder;

	if (hint == LH_Lightning)
		return stats.WeaponLevel[WT_Spell] == ST_Lightning;

	if (hint == LH_GhostArmy)
		return stats.WeaponLevel[WT_Spell] == ST_GhostArmy;

	if (hint == LH_Tornado)
		return stats.WeaponLevel[WT_Spell] == ST_Tornado;

	return true;
}

